@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.initial-delay-ms=3600000","dreamcore.knowledge.initial-delay-ms=3600000","dreamcore.plans.initial-delay-ms=3600000","dreamcore.tasks.agent-mode=off"})
class EvaluationMethodIntegrationTest {
 @Autowired EvaluationService evaluations;@Autowired EvaluationIssueService issues;@Autowired MethodService methods;@Autowired MethodSelection selection;@Autowired JdbcTemplate db;@Autowired PasswordEncoder passwords;@Autowired MaterialService materials;@LocalServerPort int port;
 UUID tenant,owner,other,platform,space,personal;static String passwordHash;JsonMapper json=new JsonMapper();
 @BeforeEach void fixture(){tenant=UUID.randomUUID();owner=UUID.randomUUID();other=UUID.randomUUID();platform=UUID.randomUUID();space=UUID.randomUUID();personal=UUID.randomUUID();if(passwordHash==null)passwordHash=passwords.encode("synthetic-evaluation-password");for(UUID a:List.of(owner,other,platform))db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,a+"@evaluation.test","评估合成用户",passwordHash);db.update("INSERT INTO platform_roles(account_id,role) VALUES (?,'PLATFORM_ADMIN')",platform);db.update("INSERT INTO tenants(id,name) VALUES (?,'评估隔离企业')",tenant);for(UUID a:List.of(owner,other))db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,'TENANT_ADMIN')",tenant,a);db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'共享评估','SHARED'),(?,?,?,'个人评估','PERSONAL')",space,tenant,owner,personal,tenant,owner);for(UUID a:List.of(owner,other))db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true)",tenant,space,a);grant(owner,space,"EVALUATION_MAINTAIN");}
 @AfterEach void cleanup(){db.update("UPDATE knowledge_runs SET status='CANCELLED' WHERE tenant_id=? AND status IN ('RUNNING','QUEUED')",tenant);db.update("DELETE FROM login_attempts WHERE bucket=?",IdentityService.hash("ip:127.0.0.1"));db.update("DELETE FROM platform_roles WHERE account_id=?",platform);}
 void grant(UUID actor,UUID workspace,String capability){db.update("INSERT INTO governance_capabilities(tenant_id,account_id,workspace_id,capability,granted_by) VALUES (?,?,?,?,?) ON CONFLICT DO NOTHING",tenant,actor,workspace,capability,owner);}
 void denied(int code,Runnable work){assertEquals(code,assertThrows(IdentityException.class,work::run).status);}
 EvaluationService.Content content(String title,List<EvaluationService.Criterion> criteria,String input,String expected,String observed){return new EvaluationService.Content(title,"REGRESSION","合成检查，保留未覆盖与缺证据情况",criteria,input,expected,observed,"未验证真实业务效果");}
 EvaluationService.Criterion criterion(String key,String dimension,String check){return new EvaluationService.Criterion(key,dimension,"REQUIRED",check,"仅核对声明的维度");}
 EvaluationService.Asset asset(String kind,EvaluationService.Content c,List<EvaluationAccess.Evidence> refs){return evaluations.create(owner,tenant,space,UUID.randomUUID(),kind,c,refs);}
 EvaluationService.Asset sample(String input,String expected,String observed){return asset("SAMPLE",content("合成样例",List.of(),input,expected,observed),List.of());}
 EvaluationService.Asset standard(){return asset("STANDARD",content("范围评价标准",List.of(criterion("exact","FACT","SYNTHETIC_EQUALS"),criterion("help","USER_EFFECT","MANUAL")),"","",""),List.of());}
 EvaluationService.Evaluation run(EvaluationService.Asset s,EvaluationService.Asset c){return evaluations.evaluate(owner,tenant,space,UUID.randomUUID(),s.version().id(),List.of(c.version().id()),null,List.of());}
 UUID task(String state,String mode){UUID conversation=UUID.randomUUID(),task=UUID.randomUUID();db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'私有任务')",conversation,tenant,space,owner);db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,execution_class) VALUES (?,?,?,?,?,'合成原任务','AGENT',?,?)",task,tenant,space,conversation,owner,state,mode);return task;}
 @Test void standardsSamplesAndJudgmentsStayImmutableAndSeparate(){var s=standard();var c=sample("合成输入","正确","错误");var r=run(s,c);assertEquals(1,r.uniqueOrigins());assertEquals("SYNTHETIC",r.modes().getFirst());assertEquals("NOT_VALIDATED",r.businessQuality());assertEquals("NOT_MADE",r.adoptionDecision());assertEquals(1,r.coverage().getFirst().fail());assertEquals(1,r.coverage().get(2).unknown());var review=evaluations.evaluate(owner,tenant,space,UUID.randomUUID(),s.version().id(),List.of(c.version().id()),r.id(),List.of(new EvaluationService.Judgment(c.version().id(),"help","PASS","仅合成样例中的人工帮助判断")));assertEquals("SUPERSEDED",evaluations.evaluation(owner,tenant,r.id()).validity());assertEquals(1,review.coverage().get(2).pass());assertEquals(1,evaluations.evaluation(owner,tenant,r.id()).coverage().get(2).unknown());denied(400,()->evaluations.evaluate(owner,tenant,space,UUID.randomUUID(),s.version().id(),List.of(c.version().id()),null,List.of(new EvaluationService.Judgment(c.version().id(),"exact","PASS","试图覆盖程序事实"))));}
 @Test void changedStandardInvalidatesOldResultsRatherThanRewritingPassRate(){var s=standard();var c=sample("输入一","A","A");var r=run(s,c);evaluations.revise(owner,tenant,s.id(),UUID.randomUUID(),s.revision(),content("新标准",s.version().content().criteria(),"","",""),List.of(),false);assertEquals("STALE",evaluations.evaluation(owner,tenant,r.id()).validity());assertEquals("范围评价标准",evaluations.get(owner,tenant,s.id(),1).version().content().title());denied(409,()->run(s,c));denied(409,()->evaluations.revise(owner,tenant,s.id(),UUID.randomUUID(),1,s.version().content(),List.of(),false));}
 @Test void duplicateOriginsDoNotInflateSampleDenominators(){var s=standard();var a=sample("同源输入","A","A");var b=sample("同源输入","改变预期不能制造新来源","不同观察");denied(409,()->evaluations.evaluate(owner,tenant,space,UUID.randomUUID(),s.version().id(),List.of(a.version().id(),b.version().id()),null,List.of()));}
 @Test void adminTitleAndPlatformDoNotConferEvaluationOrPrivateTaskRights(){denied(403,()->evaluations.create(other,tenant,space,UUID.randomUUID(),"SAMPLE",content("越权",List.of(),"A","A","A"),List.of()));grant(other,space,"EVALUATION_MAINTAIN");UUID t=task("SUCCEEDED","verification");var c=asset("SAMPLE",content("私有任务样例",List.of(),"","",""),List.of(new EvaluationAccess.Evidence("TASK",t,0,0)));denied(404,()->evaluations.get(other,tenant,c.id(),null));denied(403,()->evaluations.get(platform,tenant,c.id(),null));assertTrue(evaluations.list(other,tenant,space,"SAMPLE",0,20).items().isEmpty());denied(400,()->evaluations.create(platform,null,null,UUID.randomUUID(),"SAMPLE",content("不许上传客户任务",List.of(),"","",""),c.version().evidence()));}
 @Test void taskExecutionAndVerificationModeDoNotProveBusinessQuality(){UUID t=task("SUCCEEDED","verification");var s=asset("STANDARD",content("执行核对",List.of(criterion("ran","RUNTIME","TASK_SUCCEEDED"),criterion("quality","CONTENT_QUALITY","MANUAL")),"","",""),List.of());var c=asset("SAMPLE",content("任务样例",List.of(),"","",""),List.of(new EvaluationAccess.Evidence("TASK",t,0,0)));var r=run(s,c);assertEquals(List.of("VERIFICATION"),r.modes());assertEquals(1,r.coverage().get(3).pass());assertEquals(1,r.coverage().get(1).unknown());db.update("UPDATE conversation_tasks SET revision=revision+1 WHERE id=?",t);assertEquals("STALE",evaluations.evaluation(owner,tenant,r.id()).validity());}
 @Test void resourceEvidenceUsesActualAttemptDenominatorsAndLeavesMissingUsageUnknown(){UUID t=task("SUCCEEDED","verification");db.update("UPDATE conversation_tasks SET attempt=1 WHERE id=?",t);var evidence=new EvaluationAccess.Evidence("TASK",t,0,1);assertEquals("NOT_RECORDED",evaluations.details(owner,tenant,space,evidence).resourceCoverage());UUID attempt=UUID.randomUUID();db.update("INSERT INTO agent_attempt_usage(attempt_id,task_id,tenant_id,workspace_id,attempt_number,execution_class,status,metering_enabled) VALUES (?,?,?,?,1,'verification','SUCCEEDED',true)",attempt,t,tenant,space);db.update("INSERT INTO agent_model_requests(task_id,attempt_id,sequence,max_output_tokens) VALUES (?,?,1,512),(?,?,2,512)",t,attempt,t,attempt);db.update("UPDATE agent_model_requests SET outcome='RETURNED',input_tokens=12,output_tokens=7 WHERE attempt_id=? AND sequence=1",attempt);var d=evaluations.details(owner,tenant,space,evidence);assertEquals("NOT_A_BILL",d.costStatus());var a=d.attempts().getFirst();assertEquals(2,a.registeredRequests());assertEquals(1,a.reportedUsage());assertEquals(1,a.pendingRequests());assertEquals(12,a.knownInputTokens());denied(404,()->evaluations.details(other,tenant,space,evidence));}
 @Test void feedbackSharesTaskOriginAndWithdrawalDoesNotTurnIntoAnotherIndependentSuccess(){UUID t=task("SUCCEEDED","verification"),feedback=UUID.randomUUID();db.update("INSERT INTO feedback_entries(id,tenant_id,workspace_id,actor_id,kind,task_id,task_revision,attempt,presentation_version,presentation_revision,snapshot) VALUES (?,?,?,?,'TASK',?,0,0,'task-v1',0,'{}')",feedback,tenant,space,owner,t);db.update("INSERT INTO feedback_versions(id,feedback_id,revision,status,assessment) VALUES (?,?,1,'ACTIVE','{}')",UUID.randomUUID(),feedback);var a=asset("SAMPLE",content("任务依据",List.of(),"","",""),List.of(new EvaluationAccess.Evidence("TASK",t,0,0)));var b=asset("SAMPLE",content("同任务反馈",List.of(),"","",""),List.of(new EvaluationAccess.Evidence("FEEDBACK",feedback,1,0)));var s=standard();denied(409,()->evaluations.evaluate(owner,tenant,space,UUID.randomUUID(),s.version().id(),List.of(a.version().id(),b.version().id()),null,List.of()));var r=run(s,b);db.update("INSERT INTO feedback_versions(id,feedback_id,revision,status,assessment) VALUES (?,?,2,'WITHDRAWN','{}')",UUID.randomUUID(),feedback);db.update("UPDATE feedback_entries SET revision=2 WHERE id=?",feedback);assertEquals("STALE",evaluations.evaluation(owner,tenant,r.id()).validity());db.queryForList("SELECT scrub_evaluation_feedback(?)",feedback);assertEquals("DETAILS_UNAVAILABLE",evaluations.evaluation(owner,tenant,r.id()).validity());}
 @Test void privateCasesDoNotLeakPaginationCountsAndTaskCleanupRemovesDerivedJudgment(){UUID t=task("FAILED","verification");for(int i=0;i<21;i++)asset("SAMPLE",content("私有样例 "+i,List.of(),"","",""),List.of(new EvaluationAccess.Evidence("TASK",t,0,0)));var hidden=evaluations.list(other,tenant,space,"SAMPLE",0,20);assertTrue(hidden.items().isEmpty());assertFalse(hidden.hasMore());assertEquals(0,hidden.nextOffset());var own=evaluations.list(owner,tenant,space,"SAMPLE",0,20);assertEquals(20,own.items().size());assertTrue(own.hasMore());var s=standard();var r=run(s,own.items().getFirst());db.queryForList("SELECT scrub_evaluation_task(?)",t);assertEquals("DETAILS_UNAVAILABLE",evaluations.evaluation(owner,tenant,r.id()).validity());assertEquals(0,db.queryForObject("SELECT count(*) FROM evaluation_findings WHERE run_id=? AND note<>''",Integer.class,r.id()));}
 @Test void sourceRevocationHidesCopiesAndCleanupScrubsDerivedText(){var file=materials.upload(owner,tenant,space,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","evaluation.txt","text/plain","合成资料".getBytes()));UUID v=db.queryForObject("SELECT id FROM material_versions WHERE material_id=?",UUID.class,file.id());var c=asset("SAMPLE",content("来源标题",List.of(),"引用资料的判断","",""),List.of(new EvaluationAccess.Evidence("MATERIAL_VERSION",v,1,0)));var s=standard();var r=run(s,c);db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",space,owner);denied(404,()->evaluations.evaluation(owner,tenant,r.id()));db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true)",tenant,space,owner);db.queryForList("SELECT scrub_evaluation_material(?)",file.id());denied(404,()->evaluations.get(owner,tenant,c.id(),null));assertEquals("{}",db.queryForObject("SELECT content::text FROM evaluation_asset_versions WHERE id=?",String.class,c.version().id()));}
 @Test void issueAssignmentDoesNotGrantPrivateContentAndOutcomesAreNotTaskStatus(){UUID t=task("FAILED","verification");var c=asset("SAMPLE",content("私有错误",List.of(),"","",""),List.of(new EvaluationAccess.Evidence("TASK",t,0,0)));var i=issues.create(owner,tenant,space,UUID.randomUUID(),new EvaluationIssueService.Create(c.version().id(),null,"核查错误","CONTENT","本次输出不可用","核对并更正"));grant(other,space,"EVALUATION_MAINTAIN");denied(404,()->issues.change(owner,tenant,i.id(),UUID.randomUUID(),1,new EvaluationIssueService.Change("IN_PROGRESS",other,null,null,"交给另一管理员",List.of())));var taken=issues.change(owner,tenant,i.id(),UUID.randomUUID(),1,new EvaluationIssueService.Change("IN_PROGRESS",owner,null,null,"本人接手",List.of()));var closed=issues.change(owner,tenant,i.id(),UUID.randomUUID(),taken.revision(),new EvaluationIssueService.Change("CLOSED",owner,"ACCEPTED_TRADEOFF","HUMAN_CONFIRMATION","明确不重做，影响保留",List.of()));assertEquals("ACCEPTED_TRADEOFF",closed.outcome());assertEquals("FAILED",db.queryForObject("SELECT status FROM conversation_tasks WHERE id=?",String.class,t));denied(409,()->issues.change(owner,tenant,i.id(),UUID.randomUUID(),1,new EvaluationIssueService.Change("OPEN",null,null,null,"旧操作",List.of())));assertEquals("OPEN",issues.change(owner,tenant,i.id(),UUID.randomUUID(),closed.revision(),new EvaluationIssueService.Change("OPEN",null,null,null,"出现新证据重新处理",List.of())).status());}
 List<MethodSelection.Candidate> pool(){return List.of(new MethodSelection.Candidate(UUID.fromString("00000000-0000-0000-0000-000000000001"),space,1,0,0,Instant.parse("2026-01-01T00:00:00Z")),new MethodSelection.Candidate(UUID.fromString("00000000-0000-0000-0000-000000000002"),space,0,1,0,Instant.parse("2026-01-01T00:00:00Z")));}
 EvaluationService.Asset platformStandard(){return evaluations.create(platform,null,null,UUID.randomUUID(),"STANDARD",content("排序检查标准",List.of(criterion("order","FACT","SYNTHETIC_EQUALS")),"","",""),List.of());}
 EvaluationService.Asset rankSample(List<UUID> expected){return evaluations.create(platform,null,null,UUID.randomUUID(),"SAMPLE",content("固定排序样例",List.of(),json.writeValueAsString(new MethodService.RankingInput(pool())),json.writeValueAsString(new MethodService.Expected(expected)),"不使用人工填写观察值"),List.of());}
 MethodService.Family release(MethodSelection.Configuration config){var f=methods.create(platform,UUID.randomUUID(),"通用排序",config,"本地合成排序验证");var s=platformStandard();var c=rankSample(MethodSelection.order(pool(),config));var comparison=methods.compare(platform,UUID.randomUUID(),f.headVersion(),null,s.version().id(),List.of(c.version().id()));return methods.publish(platform,f.id(),UUID.randomUUID(),f.revision(),f.headVersion(),comparison.id());}
 @Test void comparisonExecutesBothAlgorithmsAndPublicationDoesNotAdopt(){var config=new MethodSelection.Configuration(0,1,0);var f=methods.create(platform,UUID.randomUUID(),"排序方法",config,"优先近期");var standard=platformStandard();var sample=rankSample(List.of(pool().get(1).id(),pool().get(0).id()));var r=methods.compare(platform,UUID.randomUUID(),f.headVersion(),null,standard.version().id(),List.of(sample.version().id()));assertEquals(0,r.baselinePass());assertEquals(1,r.candidatePass());assertEquals("IMPROVED_ON_SAMPLES",r.conclusion());assertEquals("NOT_VALIDATED",r.businessQuality());methods.publish(platform,f.id(),UUID.randomUUID(),f.revision(),f.headVersion(),r.id());assertEquals("BUILTIN",selection.rank(owner,tenant,pool()).items().getFirst().method().scope());}
 @Test void failedAndStaleEvidenceCannotPublishOrAdopt(){var f=methods.create(platform,UUID.randomUUID(),"错误排序",MethodSelection.DEFAULT,"合成验证");var s=platformStandard();var c=rankSample(List.of(pool().get(1).id(),pool().get(0).id()));var r=methods.compare(platform,UUID.randomUUID(),f.headVersion(),null,s.version().id(),List.of(c.version().id()));denied(409,()->methods.publish(platform,f.id(),UUID.randomUUID(),f.revision(),f.headVersion(),r.id()));var ok=release(new MethodSelection.Configuration(0,1,0));var v=ok.publishedVersion();UUID sv=db.queryForObject("SELECT c.standard_version FROM method_releases r JOIN method_comparisons c ON c.id=r.comparison_id WHERE r.version_id=?",UUID.class,v);var st=evaluations.byVersion(platform,null,sv);evaluations.revise(platform,null,st.id(),UUID.randomUUID(),st.revision(),null,null,true);grant(owner,null,"METHOD_ADOPT");denied(409,()->methods.adopt(owner,tenant,null,UUID.randomUUID(),0,"ADOPT",v,true));}
 @Test void explicitScopeAdoptionChangesActualRankingAndStopRestoresFallback(){var f=release(new MethodSelection.Configuration(0,1,0));denied(403,()->methods.adopt(owner,tenant,null,UUID.randomUUID(),0,"ADOPT",f.publishedVersion(),true));grant(owner,null,"METHOD_ADOPT");denied(400,()->methods.adopt(owner,tenant,null,UUID.randomUUID(),0,"ADOPT",f.publishedVersion(),false));var a=methods.adopt(owner,tenant,null,UUID.randomUUID(),0,"ADOPT",f.publishedVersion(),true);var selected=selection.rank(owner,tenant,pool());assertEquals(pool().get(1).id(),selected.items().getFirst().candidate().id());assertEquals(f.publishedVersion(),selected.items().getFirst().method().versionId());grant(owner,space,"METHOD_ADOPT");var local=release(MethodSelection.DEFAULT);methods.adopt(owner,tenant,space,UUID.randomUUID(),0,"ADOPT",local.publishedVersion(),true);assertEquals(pool().get(0).id(),selection.rank(owner,tenant,pool()).items().getFirst().candidate().id());methods.adopt(owner,tenant,space,UUID.randomUUID(),1,"STOP",local.publishedVersion(),false);assertEquals(pool().get(1).id(),selection.rank(owner,tenant,pool()).items().getFirst().candidate().id());methods.adopt(owner,tenant,null,UUID.randomUUID(),a.adoption().revision(),"STOP",f.publishedVersion(),false);assertEquals("BUILTIN",selection.rank(owner,tenant,pool()).items().getFirst().method().scope());}
 @Test void concurrentAdoptionHasOneWinnerAndRollbackDoesNotOverrideLaterChoice()throws Exception{var f=release(new MethodSelection.Configuration(0,1,0));var b=release(MethodSelection.DEFAULT);grant(owner,null,"METHOD_ADOPT");try(var pool=Executors.newFixedThreadPool(2)){var results=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)results.add(pool.submit(()->{try{methods.adopt(owner,tenant,null,UUID.randomUUID(),0,"ADOPT",f.publishedVersion(),true);return true;}catch(IdentityException e){assertEquals(409,e.status);return false;}}));assertEquals(1,results.stream().map(x->{try{return x.get(10,TimeUnit.SECONDS);}catch(Exception e){throw new RuntimeException(e);}}).filter(Boolean::booleanValue).count());}methods.adopt(owner,tenant,null,UUID.randomUUID(),1,"ADOPT",b.publishedVersion(),true);denied(409,()->methods.adopt(owner,tenant,null,UUID.randomUUID(),1,"ROLLBACK",f.publishedVersion(),true));assertEquals(f.publishedVersion(),methods.adopt(owner,tenant,null,UUID.randomUUID(),2,"ROLLBACK",f.publishedVersion(),true).effective().versionId());assertEquals(pool().get(1).id(),selection.rank(owner,tenant,pool()).items().getFirst().candidate().id());}
 @Test void staleCandidateCannotReplaceNewHeadAndWeightsCannotAffectAccess(){var f=release(new MethodSelection.Configuration(0,1,0));var old=methods.candidate(platform,f.id(),UUID.randomUUID(),f.revision(),MethodSelection.DEFAULT,"旧候选");methods.candidate(platform,f.id(),UUID.randomUUID(),old.revision(),new MethodSelection.Configuration(1,1,1),"新候选");denied(409,()->methods.publish(platform,f.id(),UUID.randomUUID(),old.revision(),old.headVersion(),UUID.randomUUID()));denied(400,()->methods.create(platform,UUID.randomUUID(),"无效",new MethodSelection.Configuration(Double.NaN,1,0),"非法权重"));db.update("DELETE FROM workspace_members WHERE account_id=? AND workspace_id=?",owner,space);denied(404,()->selection.rank(owner,tenant,pool()));}
 @Test void httpChecksCsrfPrivateScopeAndReturnsConflictContract()throws Exception{String base="http://127.0.0.1:"+port,path="/api/v1/tenants/"+tenant+"/evaluation/assets";var http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();assertEquals(401,http.send(HttpRequest.newBuilder(URI.create(base+path+"?workspace="+space+"&kind=SAMPLE")).GET().build(),HttpResponse.BodyHandlers.ofString()).statusCode());var csrf=json.readTree(http.send(HttpRequest.newBuilder(URI.create(base+"/api/v1/auth/csrf")).GET().build(),HttpResponse.BodyHandlers.ofString()).body());assertEquals(200,http.send(HttpRequest.newBuilder(URI.create(base+"/api/v1/auth/login")).header(csrf.get("headerName").asString(),csrf.get("token").asString()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(Map.of("email",owner+"@evaluation.test","password","synthetic-evaluation-password")))).build(),HttpResponse.BodyHandlers.ofString()).statusCode());var c=sample("HTTP输入","A","A");String body=json.writeValueAsString(Map.of("requestId",UUID.randomUUID(),"expectedRevision",99,"content",c.version().content(),"evidence",List.of(),"withdraw",false));assertEquals(403,http.send(HttpRequest.newBuilder(URI.create(base+path+"/"+c.id())).header("Content-Type","application/json").PUT(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString()).statusCode());csrf=json.readTree(http.send(HttpRequest.newBuilder(URI.create(base+"/api/v1/auth/csrf")).GET().build(),HttpResponse.BodyHandlers.ofString()).body());var response=http.send(HttpRequest.newBuilder(URI.create(base+path+"/"+c.id())).header(csrf.get("headerName").asString(),csrf.get("token").asString()).header("Content-Type","application/json").PUT(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());assertEquals(409,response.statusCode(),response.body());assertEquals("1.0",json.readTree(response.body()).get("contractVersion").asString());assertEquals(401,http.send(HttpRequest.newBuilder(URI.create(base+"/api/platform-admin/v1/methods")).GET().build(),HttpResponse.BodyHandlers.ofString()).statusCode());}
}
